CREATE VIEW dbo.IV_Q$AVAL_TRATORES_USADOS ( SeqPessoa, Pessoa, SeqQuestionario, SeqFormulario, Formulario,  DtaRealizacao, UsuInclusao, DtaAlteracao, UsuAlteracao,  Observacao,  SeqHistorico, Resultado, Processo, Departamento, LinkDocto, LinkNro, LinkSerie , ESTADO_GERAL, LATARIA_E_PINTURA, MOTOR___FUNCIONAMENT, MOTOR___VAZAMENTO_DE, MOTOR_VAZ_COMBUSTIVE, MOTOR_VAZ_AGUA, PARTE_ELETRICA___BAT, PARTE_ELET_PARTIDA, PARTE_ELETR_FUNCIONA, TRANSMISSAO___FUNCIO, TRANSMISSAO___VAZAME, EMBREAGEM___FUNCIONA, SISTEMA_DE_DIRECAO, PAINEL_DE_INSTRUMENT, TRACAO_DIANTEIRA_AUX, EIXO_DIANT_BUCH_TERM, EIXO_TRASEIRO___DIFE, EIXO_TRASEIRO___FREI, EIXO_TRASEIRO___VAZA, HIDRAULICO___FUNCION, HIDRAULICO___VAZAMEN, HIDRAULICO___LEVANTA, TOMADA_DE_FORCA___FU, VCR___QUANTIDADE_E_S, BARRA_DE_TRACAO___SI, PLATAFORMA_DE_OPERAC, POSSUI_IMPLEMENTO_IN, NOTAL_GERAL_ATRIBUID, PNEU_DIANTEIRO_DIREI, PNEU_DIAN_DIR_MARCA, PNEU_DIAN_DIR_MEDIDA, PNEU_DIAN_DIR_VIDA_U, PNEU_DIAN_DIR_AVARIA, PNEU_DIANTEIRO_ESQUE, PNEU_DIAN_ESQ_MARCA, PNEU_DIAN_ESQ_MEDIDA, PNEU_DIAN_ESQ_VIDA_U, PNEU_DIAN_ESQ_AVARIA, PNEU_TRASEIRO_DIREIT, PNEU_TRAS_DIR_MARCA, PNEU_TRAS_DIR_MEDIDA, PNEU_TRAS_DIR_VIDA_U, PNEU_TRAS_DIR_AVARIA, PNEU_TRASEITO_ESQUER, PNEU_TRAS_ESQ_MARCA, PNEU_TRAS_ESQ_MEDIDA, PNEU_TRAS_ESQ_VIDA_U, PNEU_TRAS_ESQ_AVARIA, OBSERVACOES_GERAIS, VALOR_PEDIDO_PELO_CL, VALOR_APURADO_NO_MER, VALOR_ATRIBUIDO_PARA, DATA_DE_VALIDADE_DA_)     AS SELECT PES.SEQPESSOA, PES.NOMERAZAO, QST.SEQQUESTIONARIO, FRM.SEQFORMULARIO, FRM.DESCRICAO,  QST.DTAREALIZACAO, QST.USUINCLUSAO, QST.DTAALTERACAO, QST.USUALTERACAO, QST.OBS,  QST.SEQHISTORICO, QST.RESULTADO, QST.PROCESSO, QST.DEPARTAMENTO,  QST.LINKDOCTO, QST.LINKNRO, QST.LINKSERIE , TABF.ESTADO_GERAL, TABF.LATARIA_E_PINTURA, TABF.MOTOR___FUNCIONAMENT, TABF.MOTOR___VAZAMENTO_DE, TABF.MOTOR_VAZ_COMBUSTIVE, TABF.MOTOR_VAZ_AGUA, TABF.PARTE_ELETRICA___BAT, TABF.PARTE_ELET_PARTIDA, TABF.PARTE_ELETR_FUNCIONA, TABF.TRANSMISSAO___FUNCIO, TABF.TRANSMISSAO___VAZAME, TABF.EMBREAGEM___FUNCIONA, TABF.